// Writes two small generated files next to the subject data (run by build-subject-index.mjs):
//
//  index.light.generated.ts  every subject WITHOUT its topics (names, fields, branches, semesters,
//                            chapters with topic counts): enough to list and search subjects, and tiny
//                            compared with the full data.
//  loaders.generated.ts      one on-demand loader per subject file, so a subject's chapters and topics
//                            are only downloaded when that subject is opened (the bundler splits each
//                            file into its own chunk).
//
// Pages that only list subjects use the light index; a page that needs a subject's topics loads that
// one subject. Adding a subject is still just adding a JSON file.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = "src/data/subjects";
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".json") && !f.endsWith("-sources.json"))
  .sort();

const light = files.map((f) => {
  const s = JSON.parse(readFileSync(`${dir}/${f}`, "utf8"));
  return {
    id: s.id,
    name: s.name,
    field: s.field,
    tier: s.tier,
    branches: s.branches,
    semesters: s.semesters,
    ...(s.visualSet ? { visualSet: s.visualSet } : {}),
    ...(s.teaching ? { teaching: s.teaching } : {}),
    ...(s.links ? { links: s.links } : {}),
    ...(s.offerings ? { offerings: s.offerings } : {}),
    chapters: s.chapters.map((c) => ({ id: c.id, name: c.name, topics: c.topics.length })),
  };
});

const lightSource = [
  "// Generated by scripts/build-subject-light.mjs from the subject files. Do not edit.",
  `export const subjectIndexData = ${JSON.stringify(light)} as const;`,
  "",
].join("\n");

const loaderSource = [
  "// Generated by scripts/build-subject-light.mjs from the subject files. Do not edit.",
  "/** Loads one subject's full data (chapters and topics) on demand, by subject id. */",
  "export const subjectLoaders: Record<string, () => Promise<{ default: unknown }>> = {",
  ...files.map((f) => {
    const id = JSON.parse(readFileSync(`${dir}/${f}`, "utf8")).id;
    return `  ${JSON.stringify(id)}: () => import("./${f}"),`;
  }),
  "};",
  "",
].join("\n");

function writeIfChanged(path, text) {
  let current = "";
  try {
    current = readFileSync(path, "utf8");
  } catch {
    // first run
  }
  if (current !== text) writeFileSync(path, text);
}
writeIfChanged(`${dir}/index.light.generated.ts`, lightSource);
writeIfChanged(`${dir}/loaders.generated.ts`, loaderSource);
